WITH valid AS (SELECT *, CONCAT(dept_name, '/', location) AS dept_name_location, SUBSTRING(location, 1, 3) AS location_prefix FROM departments WHERE location IS NOT NULL), latest AS (SELECT id, dept_name, dept_name_location, location_prefix FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY dept_name, location ORDER BY budget, id) AS row_num FROM valid) x WHERE row_num = 1), cleaned AS (SELECT *, UPPER(dept_name) AS dept_name_upper FROM latest WHERE dept_name = 'Legal'), eligible AS (SELECT s.* FROM cleaned s WHERE NOT EXISTS (SELECT 1 FROM employees c WHERE c.dept_id = s.id AND c.is_remote)), matched_keys AS (SELECT id, dept_name FROM eligible EXCEPT SELECT id, dept_name FROM departments WHERE location = 'Singapore'), verified AS (SELECT s.* FROM eligible s JOIN matched_keys k ON s.id = k.id AND s.dept_name = k.dept_name), stats AS (SELECT dept_name, SIZE(COLLECT_SET(dept_name)) AS num_dept_names, COUNT(CASE WHEN dept_name = 'HR' THEN 1 END) AS hr_count, COUNT(CASE WHEN dept_name = 'HR' THEN 1 END) AS hr_count_2 FROM verified GROUP BY 1) SELECT dept_name, num_dept_names, hr_count, CASE WHEN dept_name RLIKE '^(Engineering|Sales)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS dept_name_zone FROM stats ORDER BY dept_name DESC, hr_count
